import React, { useState } from "react";
import { Link, useLocation } from "react-router-dom";

const SidebarItem = ({ item }) => {
  const location = useLocation();
  const [open, setOpen] = useState(false);

  const hasChildren = item.children && item.children.length > 0;

  const isActive =
    location.pathname === item.path ||
    (hasChildren &&
      item.children.some((child) => child.path === location.pathname));

  return (
    <li className={`nav-item ${hasChildren ? "has-treeview" : ""} ${isActive ? "menu-open" : ""}`}>
      {hasChildren ? (
        <>
          <button
            onClick={() => setOpen(!open)}
            className={`nav-link d-flex justify-content-between align-items-center ${
              isActive ? "active" : ""
            }`}
          >
            <span>{item.label}</span>
            <i className={`right fas fa-angle-${open ? "down" : "left"}`}></i>
          </button>
          <ul className={`nav nav-treeview ${open ? "d-block" : "d-none"}`}>
            {item.children.map((child, idx) => (
              <li key={idx} className="nav-item">
                <Link
                  to={child.path}
                  className={`nav-link ${
                    location.pathname === child.path ? "active" : ""
                  }`}
                >
                  {child.label}
                </Link>
              </li>
            ))}
          </ul>
        </>
      ) : (
        <Link to={item.path} className={`nav-link ${isActive ? "active" : ""}`}>
          {item.label}
        </Link>
      )}
    </li>
  );
};

function Layout({ children }) {
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  const toggleSidebar = () => setSidebarCollapsed(!sidebarCollapsed);

  // Example sidebar menu structure
  const menu = [
    { label: "Dashboard", path: "/" },
    { label: "Users", path: "/users" },
    {
      label: "Departments",
      children: [
        { label: "HR", path: "/departments/hr" },
        { label: "IT", path: "/departments/it" },
      ],
    },
    {
      label: "Settings",
      children: [
        { label: "Profile", path: "/settings/profile" },
        { label: "Security", path: "/settings/security" },
      ],
    },
  ];

  return (
    <div className={`wrapper ${sidebarCollapsed ? "sidebar-collapse" : ""}`}>
      {/* Navbar */}
      <nav className="main-header navbar navbar-expand navbar-white navbar-light">
        <ul className="navbar-nav">
          <li className="nav-item">
            <button className="btn btn-light" onClick={toggleSidebar}>
              <i className="fas fa-bars"></i>
            </button>
          </li>
        </ul>
      </nav>

      {/* Sidebar */}
      <aside className="main-sidebar sidebar-dark-primary elevation-4">
        <Link to="/" className="brand-link">
          <span className="brand-text font-weight-light">ORA Admin</span>
        </Link>
        <div className="sidebar">
          <nav className="mt-2">
            <ul className="nav nav-pills nav-sidebar flex-column">
              {menu.map((item, idx) => (
                <SidebarItem key={idx} item={item} />
              ))}
            </ul>
          </nav>
        </div>
      </aside>

      {/* Content */}
      <div className="content-wrapper">
        <section className="content">
          <div className="container-fluid">{children}</div>
        </section>
      </div>
    </div>
  );
}

export default Layout;
